  'Izbriši predmet {name}': ["Delete subject {name}", "Fach {name} löschen", "Elimina la materia {name}", "Izbriši predmet {name}"],
  'Predmet »{name}« ima {count}. Ga res izbrišem?': ["“{name}” has {count}. Delete it anyway?", "„{name}“ hat {count}. Trotzdem löschen?", "«{name}» ha {count}. Eliminarla comunque?", "„{name}” ima {count}. Svejedno izbrisati?"],
  'Izbrišem predmet »{name}«?': ["Delete the subject “{name}”?", "Fach „{name}“ löschen?", "Eliminare la materia «{name}»?", "Izbrisati predmet „{name}”?"],
  'Vsaka naloga, preverjanje in kartica pripada enemu predmetu. Odpri predmet za njegove naloge.': ["Every task, test and card belongs to one subject. Open a subject to see its tasks.", "Jede Aufgabe, Prüfung und Karte gehört zu einem Fach. Öffne ein Fach, um seine Aufgaben zu sehen.", "Ogni compito, verifica e carta appartiene a una materia. Apri una materia per vederne i compiti.", "Svaki zadatak, provjera i kartica pripada jednom predmetu. Otvori predmet za njegove zadatke."],
  'Najprej ustvari predmet. Nato se odpre obrazec za nalogo, že povezan z njim.': ["Create a subject first. The task form then opens, already linked to it.", "Lege zuerst ein Fach an. Danach öffnet sich das Aufgabenformular, schon damit verknüpft.", "Prima crea una materia. Poi si apre il modulo del compito, già collegato.", "Najprije stvori predmet. Zatim se otvara obrazac za zadatak, već povezan s njim."],
  'Začni s prvim predmetom': ["Start with your first subject", "Beginne mit deinem ersten Fach", "Inizia con la prima materia", "Počni s prvim predmetom"],
  'Na primer Matematika ali Biologija. Naloge, testi in kartice se nato razvrstijo po njem.': ["For example Maths or Biology. Tasks, tests and cards are then sorted by it.", "Zum Beispiel Mathematik oder Biologie. Aufgaben, Prüfungen und Karten werden danach sortiert.", "Per esempio Matematica o Biologia. Compiti, verifiche e carte vengono ordinati di conseguenza.", "Na primjer Matematika ili Biologija. Zadaci, provjere i kartice zatim se razvrstavaju po njemu."],
  'Poišči predmet': ["Find a subject", "Fach suchen", "Cerca una materia", "Pronađi predmet"],
  'Poišči predmet…': ["Find a subject…", "Fach suchen…", "Cerca una materia…", "Pronađi predmet…"],
  'Noben predmet se ne ujema z »{search}«.': ["No subject matches “{search}”.", "Kein Fach passt zu „{search}“.", "Nessuna materia corrisponde a «{search}».", "Nijedan predmet ne odgovara „{search}”."],

  /* ── Friends ──────────────────────────────────────────────────────────── */
  'Dodaj prijatelja': ["Add friend", "Freund hinzufügen", "Aggiungi amico", "Dodaj prijatelja"],
  'Tvoja koda': ["Your code", "Dein Code", "Il tuo codice", "Tvoj kod"],
