  'Zahteva poslana': ["Request sent", "Anfrage gesendet", "Richiesta inviata", "Zahtjev poslan"],
  'Dodaj {name} med prijatelje': ["Add {name} as a friend", "{name} als Freund hinzufügen", "Aggiungi {name} agli amici", "Dodaj {name} među prijatelje"],
  'Kopiranje ni uspelo. Kodo prepiši ročno: {code}': ["Copying failed. Copy the code by hand: {code}", "Kopieren fehlgeschlagen. Übernimm den Code von Hand: {code}", "Copia non riuscita. Trascrivi il codice: {code}", "Kopiranje nije uspjelo. Prepiši kod ručno: {code}"],
  'Zahteva je že poslana ali pa sta že prijatelja.': ["A request was already sent, or you are already friends.", "Eine Anfrage wurde schon gesendet, oder ihr seid bereits befreundet.", "Una richiesta è già stata inviata, oppure siete già amici.", "Zahtjev je već poslan ili ste već prijatelji."],
  'Zahteve ni bilo mogoče poslati. Poskusi znova.': ["The request could not be sent. Try again.", "Die Anfrage konnte nicht gesendet werden. Versuch es erneut.", "Impossibile inviare la richiesta. Riprova.", "Zahtjev nije moguće poslati. Pokušaj ponovno."],
  'Preverjam kodo…': ["Checking code…", "Code wird geprüft…", "Verifica del codice…", "Provjeravam kod…"],
  'To je tvoja koda. Vpiši kodo sošolca.': ["That is your own code. Enter your classmate’s.", "Das ist dein eigener Code. Gib den deines Mitschülers ein.", "Questo è il tuo codice. Inserisci quello del compagno.", "To je tvoj kod. Upiši kod kolege."],
  'Nihče nima te kode. Preveri, ali je prepisana pravilno.': ["Nobody has this code. Check that it is typed correctly.", "Niemand hat diesen Code. Prüfe, ob er richtig eingegeben ist.", "Nessuno ha questo codice. Controlla di averlo scritto bene.", "Nitko nema taj kod. Provjeri je li ispravno upisan."],
  'Ta račun ne obstaja več.': ["This account no longer exists.", "Dieses Konto gibt es nicht mehr.", "Questo account non esiste più.", "Ovaj račun više ne postoji."],
  'Kode ni bilo mogoče preveriti. Poskusi znova.': ["The code could not be checked. Try again.", "Der Code konnte nicht geprüft werden. Versuch es erneut.", "Impossibile verificare il codice. Riprova.", "Kod nije moguće provjeriti. Pokušaj ponovno."],
  'S to osebo sta že povezana.': ["You are already connected with this person.", "Ihr seid bereits verbunden.", "Siete già collegati.", "S ovom ste osobom već povezani."],
  'Vpiši vsaj 2 črki imena.': ["Type at least 2 letters of the name.", "Gib mindestens 2 Buchstaben des Namens ein.", "Scrivi almeno 2 lettere del nome.", "Upiši barem 2 slova imena."],
  'Nihče s tem imenom. Poskusi s kodo.': ["Nobody by that name. Try their code.", "Niemand mit diesem Namen. Versuch es mit dem Code.", "Nessuno con questo nome. Prova con il codice.", "Nitko s tim imenom. Pokušaj s kodom."],
  'Želijo biti tvoji prijatelji': ["Want to be your friend", "Möchten mit dir befreundet sein", "Vogliono essere tuoi amici", "Žele biti tvoji prijatelji"],
  'Zahteva je zavrnjena.': ["Request declined.", "Anfrage abgelehnt.", "Richiesta rifiutata.", "Zahtjev je odbijen."],
  'Odgovor ni uspel. Poskusi znova.': ["That did not work. Try again.", "Das hat nicht geklappt. Versuch es erneut.", "Non è riuscito. Riprova.", "Nije uspjelo. Pokušaj ponovno."],
  'Zavrni': ["Decline", "Ablehnen", "Rifiuta", "Odbij"],
  '{name} je zdaj tvoj prijatelj.': ["{name} is now your friend.", "{name} ist jetzt dein Freund.", "{name} ora è tuo amico.", "{name} je sada tvoj prijatelj."],
  'Sprejmi': ["Accept", "Annehmen", "Accetta", "Prihvati"],
  'Moji prijatelji': ["My friends", "Meine Freunde", "I miei amici", "Moji prijatelji"],
  'Še nimaš prijateljev': ["No friends yet", "Noch keine Freunde", "Ancora nessun amico", "Još nemaš prijatelja"],
  'Dodaj sošolca s kodo, ki ti jo pošlje, ali po imenu.': ["Add a classmate with the code they send you, or by name.", "Füge Mitschüler mit dem Code hinzu, den sie dir schicken, oder über ihren Namen.", "Aggiungi un compagno con il codice che ti manda o con il nome.", "Dodaj kolegu s kodom koji ti pošalje ili po imenu."],
  'Piši': ["Message", "Schreiben", "Scrivi", "Piši"],
  'Odstranim {name} iz prijateljev?': ["Remove {name} from your friends?", "{name} aus deinen Freunden entfernen?", "Rimuovere {name} dagli amici?", "Ukloniti {name} iz prijatelja?"],
  '{name} ni več med prijatelji.': ["{name} is no longer a friend.", "{name} ist nicht mehr dein Freund.", "{name} non è più tra gli amici.", "{name} više nije među prijateljima."],
  'Prijatelja ni bilo mogoče odstraniti. Poskusi znova.': ["The friend could not be removed. Try again.", "Der Freund konnte nicht entfernt werden. Versuch es erneut.", "Impossibile rimuovere l’amico. Riprova.", "Prijatelja nije moguće ukloniti. Pokušaj ponovno."],
  'Odstrani {name} iz prijateljev': ["Remove {name} from friends", "{name} aus Freunden entfernen", "Rimuovi {name} dagli amici", "Ukloni {name} iz prijatelja"],
  'Še niso odgovorili': ["Not answered yet", "Noch keine Antwort", "Non hanno ancora risposto", "Još nisu odgovorili"],
  'Zahteva je preklicana.': ["Request withdrawn.", "Anfrage zurückgezogen.", "Richiesta ritirata.", "Zahtjev je povučen."],
  'Zahteve ni bilo mogoče preklicati. Poskusi znova.': ["The request could not be withdrawn. Try again.", "Die Anfrage konnte nicht zurückgezogen werden. Versuch es erneut.", "Impossibile ritirare la richiesta. Riprova.", "Zahtjev nije moguće povući. Pokušaj ponovno."],

